SELECT id , imageUrl, createTime,type,awardLevel,content,regionLevel,userName as teacherName,awardName,personal,supplement,awardTime,organization,school,judgeRepeat ,repeatId
FROM miniprograme.certification


            AND school = #{school}


            AND type = #{type}


            AND awardLevel = #{awardLevel}


            AND regionLevel = #{regionLevel}


            AND userName = #{userName}


            AND personal = #{personal}


            AND awardTime BETWEEN #{startDate} AND #{endDate}
